#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void depthwise_conv_kernel(const float* __restrict__ input,
                                       const float* __restrict__ kernel,
                                       float* output,
                                       int batch, int in_ch, int out_ch,
                                       int stride, int padding, int kH, int kW) {
    // Compute output height and width
    int H_in = input.size(2);
    int W_in = input.size(3);
    int H_out = (H_in + 2 * padding - kH + 1) / stride + 1;
    int W_out = (W_in + 2 * padding - kW + 1) / stride + 1;

    // Each thread computes one output element
    for (int oc = 0; oc < out_ch; ++oc) {
        for (int i = 0; i < H_out * W_out; ++i) {
            int j = i % W_out;
            int ii = i / W_out;

            float sum = 0.0f;
            for (int kh = -kH/2; kh <= kH/2; ++kh) {
                for (int kw = -kW/2; kw <= kW/2; ++kw) {
                    int ih = ii * stride + padding + kh;
                    int iw = j * stride + padding + kw;
                    if (ih >= 0 && ih < H_in && iw >= 0 && iw < W_in) {
                        // Depthwise: each output channel uses its own kernel row.
                        float val = input[batch * in_ch * H_in * W_in + oc * in_ch * H_in * W_in + ih * W_in + j];
                        sum += kernel[oc][oc] * val;   // placeholder weight (kernel shape assumed (out_ch, in_ch, kH, kW))
                    }
                }
            }
            output[batch * out_ch * H_out * W_out + oc * H_out * W_out + ii * W_out + j] = sum;
        }
    }
}

torch::Tensor depthwise_conv_cuda(torch::Tensor input, torch::Tensor kernel) {
    auto in_channels = input.channels();
    int out_ch = kernel.size(0);
    int kH = kernel.size(2);
    int kW = kernel.size(3);

    // Output dimensions
    int H_in = input.size(2);
    int W_in = input.size(3);
    int H_out = (H_in + 2 * padding - kH + 1) / stride + 1;
    int W_out = (W_in + 2 * padding - kW + 1) / stride + 1;

    auto out_shape = torch.Size(input.size(0), out_ch, H_out, W_out);
    auto out = torch::zeros_like(input);

