    const int num_blocks_h = (H_out + block_size - 1) / block_size;
    const int num_blocks_w = (W_out + block_size - 1) / block_size;

    depthwise_conv_kernel<<<input.size(0), out_ch, H_out, W_out, stride, padding, kH, kW>>>(
